input.sparql:
SELECT ?zone ?label ?sensor ?sensorClass WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?label .
  OPTIONAL { ?zone brick:hasMonitoringSensor ?sensor . }
}

SELECT ?point ?class ?ts WHERE {
  ?point a brick:ZoneTemperatureSensor .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
  OPTIONAL { ?point rdfs:label ?class }
}
